def transform(grid):
    h, w = len(grid), len(grid[0])

    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    background = max(counts, key=counts.get)

    divider_rows = {}
    divider_cols = {}
    for r, row in enumerate(grid):
        if len(set(row)) == 1 and row[0] != background:
            divider_rows.setdefault(row[0], []).append(r)
    for c in range(w):
        col = [grid[r][c] for r in range(h)]
        if len(set(col)) == 1 and col[0] != background:
            divider_cols.setdefault(col[0], []).append(c)

    colors = set(divider_rows) | set(divider_cols)
    if not colors:
        return [row[:] for row in grid]
    divider = max(colors, key=lambda v: len(divider_rows.get(v, [])) +
                                       len(divider_cols.get(v, [])))
    rows = set(divider_rows.get(divider, []))
    cols = set(divider_cols.get(divider, []))

    def segments(length, dividers):
        result = []
        start = 0
        for i in range(length):
            if i in dividers:
                if start < i:
                    result.append((start, i))
                start = i + 1
        if start < length:
            result.append((start, length))
        return result

    row_segs = segments(h, rows)
    col_segs = segments(w, cols)
    if not row_segs or not col_segs:
        return [row[:] for row in grid]

    # Repeat the pattern in the bottom-left compartment throughout the grid.
    src_r0, src_r1 = row_segs[-1]
    src_c0, src_c1 = col_segs[0]
    tile_h, tile_w = src_r1 - src_r0, src_c1 - src_c0
    out = [row[:] for row in grid]

    for r0, r1 in row_segs:
        for c0, c1 in col_segs:
            for r in range(r0, r1):
                for c in range(c0, c1):
                    out[r][c] = grid[
                        src_r0 + (r - r0) % tile_h
                    ][
                        src_c0 + (c - c0) % tile_w
                    ]
    return out
